  private sequence = 0;

  private nextId(): string {
    this.sequence += 1;
    return `notif-${this.sequence}`;
  }

  async create(input: CreateNotificationInput): Promise<Notification> {
    const notification: Notification = {
      id: this.nextId(),
      recipientId: input.recipientId,
      type: input.type,
      title: input.title,
      message: input.message,
      relatedEntityType: input.relatedEntityType,
      relatedEntityId: input.relatedEntityId,
      relatedEntityCode: input.relatedEntityCode ?? null,
      status: input.status ?? NotificationStatus.PENDING,
      createdAt: new Date('2024-01-01T00:00:00.000Z'),
      readAt: null,
    };
    this.rows.push(notification);
    return notification;
  }

  async findById(id: string): Promise<Notification | null> {
    return this.rows.find((n) => n.id === id) ?? null;
  }

  async updateStatus(
    id: string,
    status: Notification['status'],
    readAt: Date | null
  ): Promise<Notification | null> {
    const notification = this.rows.find((n) => n.id === id);
    if (!notification) {
      return null;
    }
    notification.status = status;
    notification.readAt = readAt;
    return notification;
  }
}

