    return this.request<LeaveRequestView>(`/leaves/${id}/cancel`, {
      method: 'POST',
      authenticated: true,
    });
  }

  private async request<T>(
    path: string,
    options: { method?: string; body?: string; authenticated: boolean },
  ): Promise<T> {
    const headers: Record<string, string> = {};

    if (options.body !== undefined) {
      headers['Content-Type'] = 'application/json';
    }

    if (options.authenticated) {
      const token = this.tokenStorage.getToken();
      if (token !== null) {
        headers['Authorization'] = `Bearer ${token}`;
      }
    }

    let response: Response;
    try {
      response = await fetch(path, {
        method: options.method ?? 'GET',
        headers,
        body: options.body,
      });
    } catch (cause) {
      throw new ApiError(
        cause instanceof Error ? cause.message : 'Network request failed',
        0,
      );
    }

    if (!response.ok) {
      if (response.status === 401 && options.authenticated) {
        this.tokenStorage.clear();
      }
      throw await ApiClient.toApiError(response);
    }

    return (await response.json()) as T;
  }

  private static async toApiError(response: Response): Promise<ApiError> {
    let body: ApiErrorBody | null = null;
    try {
      body = (await response.json()) as ApiErrorBody;
    } catch {
      body = null;
    }

    const message =
      typeof body?.error === 'string'
        ? body.error
        : `Request failed with status ${response.status}`;
    const code = typeof body?.code === 'string' ? body.code : undefined;

    return new ApiError(message, response.status, code);
  }
